import*as THREE from'three';import{materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,screw}from'../../modeling/parts.js';import{grove}from'./connectors.js';import{addStickers}from'./stickers.js';import{spec}from'./dimensions.js';import data from'./geometry-data.js';
const tau=Math.PI*2;
function extrude(parent,s,d,p,m,n){return mesh(parent,new THREE.ExtrudeGeometry(s,{depth:d,bevelEnabled:false,curveSegments:48}),m,p,n);}
function board(host){
 const s=new THREE.Shape(),x=10.5,y=-12,r=3.8,dy=Math.sqrt(r*r-(x-8)**2),a=Math.acos((x-8)/r);s.moveTo(-5.45,-22.2);s.lineTo(-7.4,-22.2);s.lineTo(-x,-19.1);s.lineTo(-x,y-dy);s.absarc(-8,y,r,Math.PI+a,Math.PI-a,false);s.lineTo(-x,20.7);s.lineTo(-9,22.2);s.lineTo(9,22.2);s.lineTo(x,20.7);s.lineTo(x,y+dy);s.absarc(8,y,r,a,tau-a,false);s.lineTo(x,-19.1);s.lineTo(7.4,-22.2);s.lineTo(5.45,-22.2);s.lineTo(5.45,-17.2);s.lineTo(-5.45,-17.2);s.closePath();const hole=new THREE.Path();hole.absarc(0,y,2.8,0,tau,false);s.holes.push(hole);
 const pcb=extrude(host.body,s,.8,[0,0,-1.7],materials.plastic(0x235947,{roughness:.88}),'RF433R fixed carrier PCB with real retaining through-bore,mounting reliefs and Grove notch');pcb.userData={role:'physical-pcb',inferred:true};
 const copper=materials.metal(0xc1a064,{roughness:.53}),antenna=new THREE.Group();antenna.name='RF433R fixed integrated planar PCB copper antenna installation';host.body.add(antenna);antenna.userData={role:'fixed-integrated-antenna',inferred:true,scope:'Product specifies PCB antenna;concealed planar route is an appearance envelope,not a validated antenna layout or external socket'};
 const route=[[-7,12.8],[-7,20.2],[7,20.2],[7,17.8],[-4.5,17.8],[-4.5,15.5],[4.4,15.5],[4.4,12.8],[.8,12.8]],antennaTracks=[];for(let i=1;i<route.length;i++){const[a,b]=[route[i-1],route[i]],dx=b[0]-a[0],dy=b[1]-a[1];antennaTracks.push(mesh(antenna,new THREE.BoxGeometry(Math.abs(dx)||.55,Math.abs(dy)||.55,.035),copper,[(a[0]+b[0])/2,(a[1]+b[1])/2,-.8825],'RF433R buried fixed copper antenna track '+i));}
 const dark=materials.plastic(0x262723,{roughness:.82}),metal=materials.metal(0xb9b8aa,{roughness:.5}),ceramic=materials.plastic(0xb4a17e,{roughness:.87}),receiver=new THREE.Group();receiver.name='RF433R real SYN531R SOP-8 fixed installation';receiver.position.fromArray(spec.receiver.position);host.body.add(receiver);
 const body=slab(receiver,4.92,3.95,1.34,.08,[0,0,.16],dark,[],.015);body.name='RF433R U1 SYN531R SOP-8 physical moulded body';body.userData={role:'physical-receiver-package',part:'SYN531R',package:'SOP-8',bodyMm:[4.92,3.95,1.34],inferredPlacement:true};
 const leads=[];for(const sign of[-1,1])for(let n=0;n<4;n++){const profile=new THREE.Shape();for(const[p,i]of[[[sign*1.88,.79],0],[[sign*2.27,.79],1],[[sign*2.48,.25],2],[[sign*3,.25],3],[[sign*3,.0],4],[[sign*2.30,.0],5],[[sign*2.09,.54],6],[[sign*1.88,.54],7]]){i?profile.lineTo(...p):profile.moveTo(...p);}profile.closePath();const g=new THREE.ExtrudeGeometry(profile,{depth:.4,bevelEnabled:false});g.applyMatrix4(new THREE.Matrix4().makeBasis(new THREE.Vector3(0,1,0),new THREE.Vector3(0,0,1),new THREE.Vector3(1,0,0)));leads.push(mesh(receiver,g,metal,[(n-1.5)*1.27-.2,0,0],'RF433R SYN531R SOP-8 physical gull-wing terminal '+(leads.length+1)));}
 const crystal=slab(host.body,3.2,2.5,1.1,.24,[5.4,6,-.9],metal,[],.02);crystal.name='RF433R Y1 13.51783MHz fixed metal crystal can,concealed envelope inferred';const crystalPads=[];for(const sign of[-1,1])crystalPads.push(mesh(host.body,new THREE.BoxGeometry(.5,1.3,.12),metal,[5.4+sign*1.65,6,-.84],'RF433R fixed Y1 solder end'));
 const passives=[];for(const[n,x,y,w,h]of[['L1 27nH',-4.6,11.4,1.6,.8],['L2 33nH',-2.1,11.4,1.6,.8],['C3 5pF',-4.6,9.1,1.6,.8],['C2 3.7pF',-2.1,9.1,1.6,.8],['R2 1K',-4.6,3.2,1.6,.8],['R1 22R',1.9,-1.6,1.6,.8],['C11 100nF',4.2,1.1,1.6,.8],['C4 1uF',6.8,1.1,1.6,.8],['C10 100nF',-3.2,-5.2,1.6,.8],['C1 10uF',0,-5.2,2,1.2]]){const q=slab(host.body,w,h,.55,.05,[x,y,-.9],n.startsWith('C')?ceramic:dark,[],.008);q.name='RF433R fixed '+n;passives.push(q);for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.22,h,.16),metal,[x+sign*(w/2-.1),y,-.82],'RF433R fixed passive solder end');}
 return{pcb,antenna,antennaTracks,receiver,body,leads,crystal,crystalPads,passives};
}
export function buildRF433R(host){const parts=addCadParts(host,data,{shell:materials.plastic(0xe8e9e3,{roughness:.79})}),pcb=board(host),input=grove(host),fixing=screw(host.body,[0,-12,-3.98],'back',1.25);fixing.name='RF433R fixed rear retaining hex screw';const substrate=materials.plastic(0xdfdfdc,{roughness:.86}),front=slab(host.body,...spec.labels.front.size,.1,.08,spec.labels.front.position,substrate,[],.005),back=slab(host.body,...spec.labels.back.size,.1,.08,spec.labels.back.position,substrate,[],.005);front.name='RF433R physical front adhesive film spanning native aperture and seated on original support rim';back.name='RF433R physical back adhesive film seated on native shell recess';front.userData={role:'physical-label-substrate',face:'front'};back.userData={role:'physical-label-substrate',face:'back'};host.rf433rAssembly={parts,pcb,input,fixing,labels:{front,back}};host.unitStickers=addStickers(host);}
